```
d = depth by always going left from root
lo, hi = 0, 2^d - 1
while lo <= hi:
    mid = (lo + hi) / 2
    if position mid at level d exists:
        lo = mid + 1
    else:
        hi = mid - 1
return (2^d - 1) + (hi + 1)
```

code.cpp:
class Solution {
public:
    int countNodes(TreeNode* root) {
        if (!root) return 0;

        int d = 0;
        TreeNode* node = root;
        while (node->left) {
            d++;
            node = node->left;
        }

        int lo = 0, hi = (1 << d) - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (exists(root, d, mid)) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        return (1 << d) - 1 + (hi + 1);
    }

private:
    bool exists(TreeNode* root, int d, int pos) {
        TreeNode* node = root;
        for (int i = d - 1; i >= 0; i--) {
            int bit = (pos >> i) & 1;
            if (bit == 0) {
                node = node->left;
            } else {
                node = node->right;
            }
            if (!node) return false;
        }
        return true;
    }
};
